class CookbookApp {
  constructor() {
    this.recipes = [];
    this.filteredRecipes = [];
    this.activeCategory = 'Wszystkie';
    this.searchQuery = '';
    this.sortBy = 'title-asc';
    this.showOnlyFavorites = false;

    this.currentRecipe = null;
    this.currentScale = 1.0;
    this.kitchenStep = 0;

    // LocalStorage State
    this.favorites = new Set(JSON.parse(localStorage.getItem('przepisnik_favorites') || '[]'));
    this.shoppingList = JSON.parse(localStorage.getItem('przepisnik_shopping_list') || '[]');

    // Timer State
    this.timerInterval = null;
    this.timerSeconds = 0;
    this.timerRunning = false;

    this.initElements();
    this.initAudio();
    this.bindEvents();
    this.loadData();
  }

  initElements() {
    this.dom = {
      grid: document.getElementById('recipes-grid'),
      recipesCount: document.getElementById('recipes-count'),
      searchInput: document.getElementById('search-input'),
      clearSearchBtn: document.getElementById('clear-search-btn'),
      categoryTabs: document.getElementById('category-tabs'),
      sortSelect: document.getElementById('sort-select'),
      themeToggleBtn: document.getElementById('theme-toggle-btn'),
      favFilterBtn: document.getElementById('fav-filter-btn'),
      shoppingListBtn: document.getElementById('shopping-list-btn'),
      downloadPdfBtn: document.getElementById('download-pdf-btn'),
      offlineSyncBtn: document.getElementById('offline-sync-btn'),

      // Recipe Modal
      modalBackdrop: document.getElementById('recipe-modal'),
      modalDialog: document.getElementById('recipe-modal-dialog'),
      modalCloseBtn: document.getElementById('modal-close-btn'),
      modalFavBtn: document.getElementById('modal-fav-btn'),
      modalShareBtn: document.getElementById('modal-share-btn'),
      modalPrintBtn: document.getElementById('modal-print-btn'),
      modalKitchenBtn: document.getElementById('modal-kitchen-btn'),
      modalAddShoppingBtn: document.getElementById('modal-add-shopping-btn'),

      // Modal Details
      modalTitle: document.getElementById('modal-title'),
      modalBadges: document.getElementById('modal-badges'),
      scalerBox: document.getElementById('scaler-box'),
      ingredientsList: document.getElementById('ingredients-list'),
      instructionsList: document.getElementById('instructions-list'),
      familyTipsBox: document.getElementById('family-tips-box'),
      familyTipsText: document.getElementById('family-tips-text'),
      manuscriptGallery: document.getElementById('manuscript-gallery'),

      // Lightbox
      lightboxBackdrop: document.getElementById('lightbox-backdrop'),
      lightboxImg: document.getElementById('lightbox-img'),
      lightboxCloseBtn: document.getElementById('lightbox-close-btn'),

      // Kitchen Mode
      kitchenOverlay: document.getElementById('kitchen-overlay'),
      kitchenTitle: document.getElementById('kitchen-title'),
      kitchenStepBadge: document.getElementById('kitchen-step-badge'),
      kitchenStepText: document.getElementById('kitchen-step-text'),
      kitchenPrevBtn: document.getElementById('kitchen-prev-btn'),
      kitchenNextBtn: document.getElementById('kitchen-next-btn'),
      kitchenCloseBtn: document.getElementById('kitchen-close-btn'),

      // Shopping Modal
      shoppingModal: document.getElementById('shopping-modal'),
      shoppingItemsContainer: document.getElementById('shopping-items-container'),
      shoppingCloseBtn: document.getElementById('shopping-close-btn'),
      copyShoppingBtn: document.getElementById('copy-shopping-btn'),
      clearShoppingBtn: document.getElementById('clear-shopping-btn'),

      // Offline Cache Modal
      offlineModal: document.getElementById('offline-modal'),
      offlineCloseBtn: document.getElementById('offline-close-btn'),
      offlineStatusLabel: document.getElementById('offline-status-label'),
      offlineCountLabel: document.getElementById('offline-count-label'),
      offlineProgressBar: document.getElementById('offline-progress-bar'),
      offlineDetailText: document.getElementById('offline-detail-text'),
      startCacheBtn: document.getElementById('start-cache-btn'),

      // Timer Widget
      timerWidget: document.getElementById('timer-widget'),
      timerClock: document.getElementById('timer-clock'),
      timerToggleBtn: document.getElementById('timer-toggle-btn'),
      timerResetBtn: document.getElementById('timer-reset-btn')
    };
  }

  initAudio() {
    // Synthesize gentle kitchen chime using Web Audio API
    this.playChime = () => {
      try {
        const ctx = new (window.AudioContext || window.webkitAudioContext)();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(587.33, ctx.currentTime); // D5
        osc.frequency.exponentialRampToValueAtTime(880, ctx.currentTime + 0.3); // A5
        gain.gain.setValueAtTime(0.3, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 1.2);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start();
        osc.stop(ctx.currentTime + 1.2);
      } catch (e) {
        console.log('Audio not supported or permitted');
      }
    };
  }

  normalizeStr(s) {
    return (s || '')
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/ł/g, 'l');
  }

  bindEvents() {
    // Search
    this.dom.searchInput.addEventListener('input', (e) => {
      this.searchQuery = e.target.value.trim();
      this.dom.clearSearchBtn.style.display = this.searchQuery ? 'block' : 'none';
      this.filterAndRender();
    });

    this.dom.clearSearchBtn.addEventListener('click', () => {
      this.dom.searchInput.value = '';
      this.searchQuery = '';
      this.dom.clearSearchBtn.style.display = 'none';
      this.filterAndRender();
    });

    // Sorting
    this.dom.sortSelect.addEventListener('change', (e) => {
      this.sortBy = e.target.value;
      this.filterAndRender();
    });

    // Favorites Filter
    this.dom.favFilterBtn.addEventListener('click', () => {
      this.showOnlyFavorites = !this.showOnlyFavorites;
      this.dom.favFilterBtn.classList.toggle('active', this.showOnlyFavorites);
      this.filterAndRender();
    });

    // Theme Toggle
    this.dom.themeToggleBtn.addEventListener('click', () => {
      const current = document.documentElement.getAttribute('data-theme');
      const next = current === 'dark' ? 'light' : 'dark';
      document.documentElement.setAttribute('data-theme', next);
      localStorage.setItem('przepisnik_theme', next);
      this.dom.themeToggleBtn.innerHTML = next === 'dark' ? '☀️' : '🌙';
    });

    // Restore saved theme
    const savedTheme = localStorage.getItem('przepisnik_theme') || 'light';
    document.documentElement.setAttribute('data-theme', savedTheme);
    this.dom.themeToggleBtn.innerHTML = savedTheme === 'dark' ? '☀️' : '🌙';

    // Modals
    this.dom.modalCloseBtn.addEventListener('click', () => this.closeRecipeModal());
    this.dom.modalBackdrop.addEventListener('click', (e) => {
      if (e.target === this.dom.modalBackdrop) this.closeRecipeModal();
    });

    this.dom.lightboxCloseBtn.addEventListener('click', () => this.closeLightbox());
    this.dom.lightboxBackdrop.addEventListener('click', (e) => {
      if (e.target === this.dom.lightboxBackdrop) this.closeLightbox();
    });

    // Shopping list events
    this.dom.shoppingListBtn.addEventListener('click', () => this.openShoppingModal());
    this.dom.shoppingCloseBtn.addEventListener('click', () => this.closeShoppingModal());
    this.dom.shoppingModal.addEventListener('click', (e) => {
      if (e.target === this.dom.shoppingModal) this.closeShoppingModal();
    });
    this.dom.modalAddShoppingBtn.addEventListener('click', () => this.addCurrentRecipeToShoppingList());
    this.dom.copyShoppingBtn.addEventListener('click', () => this.copyShoppingListToClipboard());
    this.dom.clearShoppingBtn.addEventListener('click', () => this.clearShoppingList());

    // Print recipe button
    this.dom.modalPrintBtn.addEventListener('click', () => window.print());

    // Share recipe button
    if (this.dom.modalShareBtn) {
      this.dom.modalShareBtn.addEventListener('click', () => this.shareCurrentRecipe());
    }

    // Offline cache modal events
    if (this.dom.offlineSyncBtn) {
      this.dom.offlineSyncBtn.addEventListener('click', () => this.openOfflineModal());
    }
    if (this.dom.offlineCloseBtn) {
      this.dom.offlineCloseBtn.addEventListener('click', () => this.closeOfflineModal());
    }
    if (this.dom.offlineModal) {
      this.dom.offlineModal.addEventListener('click', (e) => {
        if (e.target === this.dom.offlineModal) this.closeOfflineModal();
      });
    }
    if (this.dom.startCacheBtn) {
      this.dom.startCacheBtn.addEventListener('click', () => this.cacheAllImages());
    }

    // Kitchen mode
    this.dom.modalKitchenBtn.addEventListener('click', () => this.openKitchenMode());

    // Kitchen mode events
    this.dom.kitchenPrevBtn.addEventListener('click', () => this.changeKitchenStep(-1));
    this.dom.kitchenNextBtn.addEventListener('click', () => this.changeKitchenStep(1));
    this.dom.kitchenCloseBtn.addEventListener('click', () => this.closeKitchenMode());

    // Screen Wake Lock visibility listener
    document.addEventListener('visibilitychange', () => {
      if (this.wakeLock !== null && document.visibilityState === 'visible' && this.dom.kitchenOverlay.classList.contains('open')) {
        this.requestWakeLock();
      }
    });

    // Timer controls
    this.dom.timerToggleBtn.addEventListener('click', () => this.toggleTimer());
    this.dom.timerResetBtn.addEventListener('click', () => this.resetTimer());

    // Keyboard navigation (Escape to close modals)
    window.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        if (this.dom.lightboxBackdrop.classList.contains('open')) {
          this.closeLightbox();
        } else if (this.dom.kitchenOverlay.classList.contains('open')) {
          this.closeKitchenMode();
        } else if (this.dom.offlineModal && this.dom.offlineModal.classList.contains('open')) {
          this.closeOfflineModal();
        } else if (this.dom.shoppingModal.classList.contains('open')) {
          this.closeShoppingModal();
        } else if (this.dom.modalBackdrop.classList.contains('open')) {
          this.closeRecipeModal();
        }
      }
      if (this.dom.kitchenOverlay.classList.contains('open')) {
        if (e.key === 'ArrowRight' || e.key === 'Space') this.changeKitchenStep(1);
        if (e.key === 'ArrowLeft') this.changeKitchenStep(-1);
      }
    });
  }

  async loadData() {
    try {
      const resp = await fetch('recipes.json');
      if (resp.ok) {
        this.recipes = await resp.json();
      } else {
        this.recipes = EMBEDDED_RECIPES;
      }
    } catch (err) {
      console.log('Fetching local file restricted, using embedded fallback database');
      this.recipes = EMBEDDED_RECIPES;
    }

    this.renderCategoryTabs();
    this.filterAndRender();
    this.checkOfflineCacheStatus();
  }

  renderCategoryTabs() {
    const counts = {};
    this.recipes.forEach(r => {
      counts[r.category] = (counts[r.category] || 0) + 1;
    });

    const categories = ['Wszystkie', 'Dania główne', 'Zupy', 'Ciasta i wypieki', 'Desery i słodkości', 'Sałatki i surówki', 'Przetwory', 'Sosy i dodatki'];
    
    this.dom.categoryTabs.innerHTML = categories.map(cat => {
      const count = cat === 'Wszystkie' ? this.recipes.length : (counts[cat] || 0);
      const isActive = cat === this.activeCategory ? 'active' : '';
      return `
        <button class="cat-tab-btn ${isActive}" data-category="${cat}">
          ${cat}
          <span class="cat-badge-count">${count}</span>
        </button>
      `;
    }).join('');

    this.dom.categoryTabs.querySelectorAll('.cat-tab-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        this.dom.categoryTabs.querySelectorAll('.cat-tab-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        this.activeCategory = btn.getAttribute('data-category');
        this.filterAndRender();
      });
    });
  }

  filterAndRender() {
    let result = [...this.recipes];

    // Filter by category
    if (this.activeCategory !== 'Wszystkie') {
      result = result.filter(r => r.category === this.activeCategory);
    }

    // Filter by favorites
    if (this.showOnlyFavorites) {
      result = result.filter(r => this.favorites.has(r.id));
    }

    // Filter by search query (diacritic-insensitive & robust)
    if (this.searchQuery) {
      const q = this.normalizeStr(this.searchQuery);
      result = result.filter(r => {
        const titleMatch = this.normalizeStr(r.title).includes(q);
        const catMatch = this.normalizeStr(r.category).includes(q);
        const tagsMatch = r.tags && r.tags.some(t => this.normalizeStr(t).includes(q));
        const ingsMatch = r.ingredients && r.ingredients.some(i => this.normalizeStr(i.name || i.item).includes(q));
        const instrMatch = r.instructions && r.instructions.some(ins => this.normalizeStr(ins).includes(q));
        const tipsMatch = r.tips && this.normalizeStr(Array.isArray(r.tips) ? r.tips.join(' ') : r.tips).includes(q);
        return titleMatch || catMatch || tagsMatch || ingsMatch || instrMatch || tipsMatch;
      });
    }

    // Sorting
    result.sort((a, b) => {
      if (this.sortBy === 'title-asc') return a.title.localeCompare(b.title, 'pl');
      if (this.sortBy === 'title-desc') return b.title.localeCompare(a.title, 'pl');
      if (this.sortBy === 'time-asc') {
        const tA = parseInt(a.prep_time) || 30;
        const tB = parseInt(b.prep_time) || 30;
        return tA - tB;
      }
      return 0;
    });

    this.filteredRecipes = result;
    this.dom.recipesCount.textContent = `${result.length} ${result.length === 1 ? 'przepis' : (result.length < 5 ? 'przepisy' : 'przepisów')}`;

    if (result.length === 0) {
      this.dom.grid.innerHTML = `
        <div style="grid-column: 1/-1; text-align: center; padding: 4rem 1rem; color: var(--text-muted);">
          <div style="font-size: 3rem; margin-bottom: 1rem;">🔍</div>
          <h3 style="font-family: var(--font-serif); font-size: 1.5rem; margin-bottom: 0.5rem; color: var(--text-main);">Nie znaleziono przepisów</h3>
          <p>Spróbuj zmienić słowo kluczowe lub wybrać inną kategorię.</p>
        </div>
      `;
      return;
    }

    this.dom.grid.innerHTML = result.map(recipe => this.renderRecipeCard(recipe)).join('');

    // Attach card event listeners
    this.dom.grid.querySelectorAll('.recipe-card').forEach(card => {
      const id = card.getAttribute('data-id');
      card.addEventListener('click', (e) => {
        if (e.target.closest('.card-fav-btn')) return;
        const tagBtn = e.target.closest('.card-tag-btn');
        if (tagBtn) {
          e.stopPropagation();
          this.filterByTag(tagBtn.getAttribute('data-tag'));
          return;
        }
        const recipe = this.recipes.find(r => r.id === id);
        if (recipe) this.openRecipeModal(recipe);
      });

      const favBtn = card.querySelector('.card-fav-btn');
      if (favBtn) {
        favBtn.addEventListener('click', (e) => {
          e.stopPropagation();
          this.toggleFavorite(id);
        });
      }
    });
  }

  renderRecipeCard(r) {
    const isFav = this.favorites.has(r.id);
    const favClass = isFav ? 'is-favorite' : '';
    const imgUrl = `images/${r.image}`;
    const ingsPreview = r.ingredients 
      ? r.ingredients.slice(0, 4).map(i => i.name || i.item || '').filter(Boolean).join(', ') + (r.ingredients.length > 4 ? '...' : '') 
      : '';
    const tagsRow = r.tags && r.tags.length > 0
      ? `<div class="card-tags-row">${r.tags.slice(0, 3).map(t => `<button class="recipe-tag-btn card-tag-btn" data-tag="${t}">#${t}</button>`).join('')}</div>`
      : '';

    return `
      <article class="recipe-card" data-id="${r.id}">
        <div class="card-media-wrapper">
          <img class="card-img" src="${imgUrl}" alt="${r.title}" loading="lazy" onerror="this.src='https://images.unsplash.com/photo-1495521821757-a1efb6729352?auto=format&fit=crop&w=600&q=80'">
          <div class="card-media-gradient"></div>
          <span class="card-category-badge">${r.category}</span>
          <button class="card-fav-btn ${favClass}" title="${isFav ? 'Usuń z ulubionych' : 'Dodaj do ulubionych'}">
            ${isFav ? '❤️' : '🤍'}
          </button>
          <div class="card-manuscript-tag">
            <span>✍️</span> Oryginalny rękopis
          </div>
        </div>
        <div class="card-body">
          <div class="card-meta-row">
            <span class="card-meta-item">⏱️ ${r.prep_time || '20 min'}</span>
            <span>•</span>
            <span class="card-meta-item">🍽️ ${r.servings || 4}</span>
          </div>
          <h3 class="card-title">${r.title}</h3>
          <p class="card-ingredients-preview">${ingsPreview}</p>
          ${tagsRow}
          <div class="card-footer">
            <span class="card-difficulty-badge">Poziom: ${r.difficulty || 'Średni'}</span>
            <span class="card-view-link">Zobacz przepis →</span>
          </div>
        </div>
      </article>
    `;
  }

  toggleFavorite(id) {
    if (this.favorites.has(id)) {
      this.favorites.delete(id);
    } else {
      this.favorites.add(id);
    }
    localStorage.setItem('przepisnik_favorites', JSON.stringify([...this.favorites]));
    
    // Update card icons
    document.querySelectorAll(`.recipe-card[data-id="${id}"] .card-fav-btn`).forEach(btn => {
      const isFav = this.favorites.has(id);
      btn.classList.toggle('is-favorite', isFav);
      btn.innerHTML = isFav ? '❤️' : '🤍';
    });

    // Update modal fav icon if open
    if (this.currentRecipe && this.currentRecipe.id === id) {
      const isFav = this.favorites.has(id);
      this.dom.modalFavBtn.innerHTML = isFav ? '❤️' : '🤍';
      this.dom.modalFavBtn.classList.toggle('is-favorite', isFav);
    }

    if (this.showOnlyFavorites) {
      this.filterAndRender();
    }
  }

  openRecipeModal(recipe) {
    this.currentRecipe = recipe;
    this.currentScale = 1.0;

    // Header & Badges
    this.dom.modalTitle.textContent = recipe.title;
    const isFav = this.favorites.has(recipe.id);
    this.dom.modalFavBtn.innerHTML = isFav ? '❤️' : '🤍';
    this.dom.modalFavBtn.classList.toggle('is-favorite', isFav);

    const tagsHtml = recipe.tags && recipe.tags.length > 0 
      ? recipe.tags.map(t => `<button class="recipe-tag-btn modal-tag-btn" data-tag="${t}">#${t}</button>`).join(' ')
      : '';

    this.dom.modalBadges.innerHTML = `
      <span class="modal-badge" style="color: var(--accent-primary); font-weight: 700;">📂 ${recipe.category}</span>
      <span class="modal-badge">⏱️ Przygotowanie: ${recipe.prep_time || '20 min'}</span>
      <span class="modal-badge">🔥 Gotowanie/pieczenie: ${recipe.cook_time || '30 min'}</span>
      <span class="modal-badge">🍽️ Porcje: ${recipe.servings || 4}</span>
      <span class="modal-badge">⭐ Poziom: ${recipe.difficulty || 'Średni'}</span>
      ${tagsHtml}
    `;

    this.dom.modalBadges.querySelectorAll('.modal-tag-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        this.filterByTag(btn.getAttribute('data-tag'));
      });
    });

    // Render Scaler
    this.renderScaler();
    this.renderIngredients();
    this.renderInstructions();

    // Family Tips
    if (recipe.tips && recipe.tips.length > 0) {
      this.dom.familyTipsBox.style.display = 'block';
      this.dom.familyTipsText.innerHTML = Array.isArray(recipe.tips) 
        ? recipe.tips.map(t => `<p style="margin-bottom: 0.35rem;">• ${t}</p>`).join('')
        : recipe.tips;
    } else {
      this.dom.familyTipsBox.style.display = 'none';
    }

    // Manuscript photos
    const imgs = recipe.source_images && recipe.source_images.length > 0 ? recipe.source_images : [recipe.image];
    this.dom.manuscriptGallery.innerHTML = imgs.map(img => `
      <div class="manuscript-thumb-wrapper" data-src="images/${img}">
        <img class="manuscript-thumb-img" src="images/${img}" alt="Oryginalny rękopis">
        <div class="manuscript-zoom-overlay">🔍 Kliknij, aby powiększyć</div>
      </div>
    `).join('');

    this.dom.manuscriptGallery.querySelectorAll('.manuscript-thumb-wrapper').forEach(w => {
      w.addEventListener('click', () => {
        this.openLightbox(w.getAttribute('data-src'));
      });
    });

    // Open dialog
    this.dom.modalBackdrop.classList.add('open');
    document.body.style.overflow = 'hidden';
  }

  closeRecipeModal() {
    this.dom.modalBackdrop.classList.remove('open');
    document.body.style.overflow = '';
  }

  renderScaler() {
    const scales = [0.5, 1, 1.5, 2, 3];
    this.dom.scalerBox.innerHTML = `
      <div class="scaler-info">
        <span>Przelicznik porcji:</span>
        <strong style="color: var(--accent-primary); font-size: 1.1rem;">${Math.round((parseInt(this.currentRecipe.servings) || 4) * this.currentScale)} porcji (${this.currentScale}x)</strong>
      </div>
      <div class="scaler-buttons">
        ${scales.map(s => `
          <button class="scale-btn ${s === this.currentScale ? 'active' : ''}" data-scale="${s}">
            ${s}x
          </button>
        `).join('')}
      </div>
    `;

    this.dom.scalerBox.querySelectorAll('.scale-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        this.currentScale = parseFloat(btn.getAttribute('data-scale'));
        this.renderScaler();
        this.renderIngredients();
      });
    });
  }

  renderIngredients() {
    if (!this.currentRecipe || !this.currentRecipe.ingredients) return;

    this.dom.ingredientsList.innerHTML = this.currentRecipe.ingredients.map((ing, idx) => {
      let formattedAmount = '';
      if (ing.amount) {
        const str = String(ing.amount).trim();
        const match = str.match(/^([\d.,\/]+)\s*(.*)$/);
        if (match && this.currentScale !== 1.0) {
          let num = 0;
          if (match[1].includes('/')) {
            const parts = match[1].split('/');
            num = parseFloat(parts[0]) / parseFloat(parts[1]);
          } else {
            num = parseFloat(match[1].replace(',', '.'));
          }
          if (!isNaN(num)) {
            const scaled = num * this.currentScale;
            const rounded = Math.round(scaled * 10) / 10;
            formattedAmount = `${String(rounded).replace('.', ',')} ${match[2]}`.trim();
          } else {
            formattedAmount = str;
          }
        } else {
          formattedAmount = str;
        }
      }

      const ingName = ing.name || ing.item || '';

      return `
        <label class="ingredient-item" data-idx="${idx}">
          <input type="checkbox" class="ing-checkbox">
          <div>
            <span class="ing-amount">${formattedAmount}</span>
            <span class="ing-name">${ingName}</span>
          </div>
        </label>
      `;
    }).join('');

    this.dom.ingredientsList.querySelectorAll('.ingredient-item').forEach(item => {
      const cb = item.querySelector('.ing-checkbox');
      cb.addEventListener('change', () => {
        item.classList.toggle('checked', cb.checked);
      });
    });
  }

  renderInstructions() {
    if (!this.currentRecipe || !this.currentRecipe.instructions) return;

    this.dom.instructionsList.innerHTML = this.currentRecipe.instructions.map((step, idx) => {
      // Look for minutes in step text
      const timeMatch = step.match(/(\d+)\s*(?:-|–|\s+do\s+)?(\d+)?\s*(?:minut|min\b)/i);
      let timerButtonHtml = '';
      if (timeMatch) {
        const minutes = parseInt(timeMatch[2] || timeMatch[1]);
        timerButtonHtml = `
          <div>
            <button class="step-timer-btn" data-minutes="${minutes}">
              ⏱️ Włącz minutnik: ${minutes} min
            </button>
          </div>
        `;
      }

      return `
        <div class="step-card">
          <div class="step-number">${idx + 1}</div>
          <div class="step-content">
            <p>${step}</p>
            ${timerButtonHtml}
          </div>
        </div>
      `;
    }).join('');

    this.dom.instructionsList.querySelectorAll('.step-timer-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const mins = parseInt(btn.getAttribute('data-minutes'));
        this.startTimer(mins * 60);
      });
    });
  }

  // Timer Widget
  startTimer(seconds) {
    this.resetTimer();
    this.timerSeconds = seconds;
    this.timerRunning = true;
    this.dom.timerWidget.classList.add('active');
    this.dom.timerToggleBtn.textContent = '⏸️ Pauza';
    this.updateTimerDisplay();

    this.timerInterval = setInterval(() => {
      if (this.timerRunning) {
        this.timerSeconds--;
        this.updateTimerDisplay();
        if (this.timerSeconds <= 0) {
          this.onTimerComplete();
        }
      }
    }, 1000);
  }

  toggleTimer() {
    if (this.timerSeconds <= 0) return;
    this.timerRunning = !this.timerRunning;
    this.dom.timerToggleBtn.textContent = this.timerRunning ? '⏸️ Pauza' : '▶️ Wznów';
  }

  resetTimer() {
    clearInterval(this.timerInterval);
    this.timerRunning = false;
    this.timerSeconds = 0;
    this.dom.timerWidget.classList.remove('active');
  }

  updateTimerDisplay() {
    const mins = Math.floor(this.timerSeconds / 60);
    const secs = this.timerSeconds % 60;
    this.dom.timerClock.textContent = `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
  }

  onTimerComplete() {
    clearInterval(this.timerInterval);
    this.timerRunning = false;
    this.playChime();
    alert('⏰ Czas minął! Sprawdź potrawę w piekarniku lub na płycie.');
    this.resetTimer();
  }

  // Lightbox
  openLightbox(src) {
    this.dom.lightboxImg.src = src;
    this.dom.lightboxBackdrop.classList.add('open');
  }

  closeLightbox() {
    this.dom.lightboxBackdrop.classList.remove('open');
    this.dom.lightboxImg.src = '';
  }

  // Kitchen Mode
  openKitchenMode() {
    if (!this.currentRecipe) return;
    this.kitchenStep = 0;
    this.dom.kitchenTitle.textContent = this.currentRecipe.title;
    this.updateKitchenDisplay();
    this.requestWakeLock();
    this.dom.kitchenOverlay.classList.add('open');
  }

  closeKitchenMode() {
    this.releaseWakeLock();
    this.dom.kitchenOverlay.classList.remove('open');
  }

  changeKitchenStep(delta) {
    const steps = this.currentRecipe.instructions || [];
    const newIdx = this.kitchenStep + delta;
    if (newIdx >= 0 && newIdx < steps.length) {
      this.kitchenStep = newIdx;
      this.updateKitchenDisplay();
    }
  }

  updateKitchenDisplay() {
    const steps = this.currentRecipe.instructions || [];
    this.dom.kitchenStepBadge.textContent = `Krok ${this.kitchenStep + 1} z ${steps.length}`;
    this.dom.kitchenStepText.textContent = steps[this.kitchenStep] || '';
    this.dom.kitchenPrevBtn.disabled = this.kitchenStep === 0;
    this.dom.kitchenNextBtn.textContent = this.kitchenStep === steps.length - 1 ? 'Zakończ gotowanie 🎉' : 'Następny krok →';
  }

  // Shopping List
  addCurrentRecipeToShoppingList() {
    if (!this.currentRecipe || !this.currentRecipe.ingredients) return;
    const newItems = this.currentRecipe.ingredients.map(i => ({
      name: `${i.amount || ''} ${i.name || i.item || ''}`.trim(),
      recipe: this.currentRecipe.title,
      checked: false
    }));

    this.shoppingList.push(...newItems);
    localStorage.setItem('przepisnik_shopping_list', JSON.stringify(this.shoppingList));
    alert(`Dodano ${newItems.length} składników do Twojej listy zakupów!`);
  }

  openShoppingModal() {
    this.renderShoppingList();
    this.dom.shoppingModal.classList.add('open');
  }

  closeShoppingModal() {
    this.dom.shoppingModal.classList.remove('open');
  }

  renderShoppingList() {
    if (this.shoppingList.length === 0) {
      this.dom.shoppingItemsContainer.innerHTML = '<p style="text-align: center; color: var(--text-muted); padding: 2rem;">Twoja lista zakupów jest pusta. Dodaj składniki z dowolnego przepisu!</p>';
      return;
    }

    this.dom.shoppingItemsContainer.innerHTML = this.shoppingList.map((item, idx) => `
      <div class="shopping-item ${item.checked ? 'checked' : ''}">
        <label style="display: flex; align-items: center; gap: 0.65rem; cursor: pointer; flex: 1;">
          <input type="checkbox" class="ing-checkbox" data-idx="${idx}" ${item.checked ? 'checked' : ''}>
          <span>${item.name} <small style="color: var(--text-dim); display: block; font-size: 0.75rem;">(${item.recipe})</small></span>
        </label>
        <button class="remove-shop-btn" data-idx="${idx}" style="background: none; border: none; cursor: pointer; color: var(--text-dim); font-size: 1.1rem;">🗑️</button>
      </div>
    `).join('');

    this.dom.shoppingItemsContainer.querySelectorAll('.ing-checkbox').forEach(cb => {
      cb.addEventListener('change', () => {
        const idx = parseInt(cb.getAttribute('data-idx'));
        this.shoppingList[idx].checked = cb.checked;
        localStorage.setItem('przepisnik_shopping_list', JSON.stringify(this.shoppingList));
        this.renderShoppingList();
      });
    });

    this.dom.shoppingItemsContainer.querySelectorAll('.remove-shop-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const idx = parseInt(btn.getAttribute('data-idx'));
        this.shoppingList.splice(idx, 1);
        localStorage.setItem('przepisnik_shopping_list', JSON.stringify(this.shoppingList));
        this.renderShoppingList();
      });
    });
  }

  copyShoppingListToClipboard() {
    if (this.shoppingList.length === 0) return;
    const text = '🛒 LISTA ZAKUPÓW - RODZINNY PRZEPIŚNIK:\n\n' +
      this.shoppingList.map(i => `${i.checked ? '[x]' : '[ ]'} ${i.name} (${i.recipe})`).join('\n');
    navigator.clipboard.writeText(text).then(() => {
      alert('Skopiowano listę zakupów do schowka!');
    });
  }

  clearShoppingList() {
    if (confirm('Czy na pewno chcesz wyczyścić całą listę zakupów?')) {
      this.shoppingList = [];
      localStorage.removeItem('przepisnik_shopping_list');
      this.renderShoppingList();
    }
  }

  // Recipe Sharing (Web Share API)
  shareCurrentRecipe() {
    if (!this.currentRecipe) return;
    const r = this.currentRecipe;
    const shareText = `📖 ${r.title}\nKategoria: ${r.category} | Czas: ${r.prep_time} | Porcje: ${r.servings}\n\n🥗 SKŁADNIKI:\n` +
      r.ingredients.map(i => `• ${i.amount || ''} ${i.name || i.item || ''}`.trim()).join('\n') +
      `\n\n👩‍🍳 PRZYGOTOWANIE:\n` +
      r.instructions.map((ins, idx) => `${idx + 1}. ${ins}`).join('\n') +
      (r.tips ? `\n\n💡 WSKAZÓWKA BABCI: ${Array.isArray(r.tips) ? r.tips.join(' ') : r.tips}` : '') +
      `\n\n— Rodzinny Przepiśnik Domowy`;

    if (navigator.share) {
      navigator.share({
        title: r.title,
        text: shareText
      }).catch(err => {
        if (err.name !== 'AbortError') {
          this.fallbackShareToClipboard(shareText);
        }
      });
    } else {
      this.fallbackShareToClipboard(shareText);
    }
  }

  fallbackShareToClipboard(text) {
    navigator.clipboard.writeText(text).then(() => {
      alert('📋 Przepis został pomyślnie skopiowany do schowka! Możesz go wkleić do wiadomości lub e-maila.');
    }).catch(() => {
      alert('Nie udało się skopiować do schowka.');
    });
  }

  // Tag Filtering Navigation
  filterByTag(tag) {
    this.closeRecipeModal();
    if (this.dom.offlineModal) this.closeOfflineModal();
    this.dom.searchInput.value = tag;
    this.searchQuery = tag;
    this.activeCategory = 'Wszystkie';
    this.renderCategoryTabs();
    this.filterAndRender();
    this.dom.grid.scrollIntoView({ behavior: 'smooth' });
  }

  // Screen Wake Lock API for Kitchen Mode
  async requestWakeLock() {
    if ('wakeLock' in navigator) {
      try {
        this.wakeLock = await navigator.wakeLock.request('screen');
        const badge = document.getElementById('kitchen-wake-badge');
        if (badge) badge.style.display = 'inline-block';
      } catch (err) {
        console.warn('Wake Lock niedostępny:', err);
      }
    }
  }

  releaseWakeLock() {
    if (this.wakeLock) {
      this.wakeLock.release().then(() => {
        this.wakeLock = null;
      }).catch(() => {});
    }
  }

  // Offline Cache Manager for 100% Offline PWA
  getAllImageUrls() {
    const urls = new Set();
    this.recipes.forEach(r => {
      if (r.image) urls.add(`images/${r.image}`);
      if (r.source_images) r.source_images.forEach(img => urls.add(`images/${img}`));
    });
    return Array.from(urls);
  }

  async checkOfflineCacheStatus() {
    if (!('caches' in window)) return;
    try {
      const cache = await caches.open('przepisnik-v1');
      const urls = this.getAllImageUrls();
      let cachedCount = 0;
      for (const url of urls) {
        const match = await cache.match(url);
        if (match) cachedCount++;
      }
      this.updateOfflineUI(cachedCount, urls.length);
    } catch (err) {
      console.warn('Cache check warning:', err);
    }
  }

  updateOfflineUI(cached, total) {
    if (!this.dom.offlineCountLabel) return;
    const pct = total > 0 ? Math.round((cached / total) * 100) : 0;
    this.dom.offlineCountLabel.textContent = `${cached} / ${total} (${pct}%)`;
    this.dom.offlineProgressBar.style.width = `${pct}%`;
    if (cached >= total && total > 0) {
      this.dom.offlineStatusLabel.textContent = 'Status: Zapisano w 100%';
      this.dom.offlineDetailText.innerHTML = '🎉 Wszystkie 154 zdjęcia są trwale zapisane w pamięci urządzenia. Aplikacja działa bez Internetu!';
      this.dom.startCacheBtn.disabled = true;
      this.dom.startCacheBtn.innerHTML = '✅ Wszystkie zdjęcia zapisane offline';
      this.dom.offlineSyncBtn.innerHTML = '<span>✅</span> <span class="btn-text">Offline gotowe</span>';
    } else {
      this.dom.offlineStatusLabel.textContent = 'Status pamięci:';
      this.dom.offlineDetailText.textContent = `W pamięci znajduje się ${cached} z ${total} zdjęć. Kliknij poniżej, aby pobrać resztę.`;
    }
  }

  openOfflineModal() {
    this.checkOfflineCacheStatus();
    this.dom.offlineModal.classList.add('open');
  }

  closeOfflineModal() {
    this.dom.offlineModal.classList.remove('open');
  }

  async cacheAllImages() {
    if (!('caches' in window)) {
      alert('Pamięć podręczna Cache Storage nie jest dostępna w Twojej przeglądarce.');
      return;
    }
    const urls = this.getAllImageUrls();
    const cache = await caches.open('przepisnik-v1');
    this.dom.startCacheBtn.disabled = true;
    this.dom.startCacheBtn.innerHTML = '⏳ Pobieranie zdjęć w toku...';

    let done = 0;
    for (const url of urls) {
      try {
        const has = await cache.match(url);
        if (!has) {
          await cache.add(url);
        }
      } catch (e) {
        console.warn('Błąd pobierania do cache:', url, e);
      }
      done++;
      const pct = Math.round((done / urls.length) * 100);
      this.dom.offlineProgressBar.style.width = `${pct}%`;
      this.dom.offlineCountLabel.textContent = `${done} / ${urls.length} (${pct}%)`;
      this.dom.offlineDetailText.textContent = `Pobieranie: ${url.replace('images/', '')}...`;
    }

    this.updateOfflineUI(done, urls.length);
  }
}

// Initialize when DOM ready
document.addEventListener('DOMContentLoaded', () => {
  window.app = new CookbookApp();

  // Register PWA Service Worker for offline support
  if ('serviceWorker' in navigator && (location.protocol === 'http:' || location.protocol === 'https:')) {
    navigator.serviceWorker.register('./sw.js').then((reg) => {
      console.log('Przepisnik: Service Worker aktywny (100% tryb offline gotowy)');
    }).catch((err) => {
      console.log('Przepisnik: Service Worker:', err);
    });
  }

  // Handle PWA installation prompt on Android and Desktop
  let deferredPrompt = null;
  const installBtn = document.getElementById('install-pwa-btn');
  window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault();
    deferredPrompt = e;
    if (installBtn) {
      installBtn.style.display = 'inline-flex';
      installBtn.addEventListener('click', () => {
        installBtn.style.display = 'none';
        deferredPrompt.prompt();
        deferredPrompt.userChoice.then(() => {
          deferredPrompt = null;
        });
      });
    }
  });
});
